fn gcd(a: Int, b: Int) -> Int {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn main() {
    print(gcd(252, 105))
}

fn gcd(a: Int, b: Int) -> Int {
    if b == 0 {
        return a
    }
    return gcd(b, a % b)
}

fn main() {
    let a = 252
    let b = 105
    print(gcd(a, b))
}

fn gcd(a: i32, b: i32) -> i32 {
    let mut tmp;
    let mut s = a;
    let mut t = b;
    while t != 0 {
        tmp = s % t;
        (s, t) = (t, tmp);
    }
    s
}

fn main() {
    println!("{}", gcd(252, 105));
}

fn is_prime(n: Int) -> Bool {
    if n <= 1 {
        return False
    }
    for i in range(2, trunc(n.sqrt())) {
        if n % i == 0 {
            return False
        }
    }
    True
}

